import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import React from "react";

export const fps = 25;
export const durationInFrames = 750;

const COLORS = {
  accent: "#9EA2A8",
  light: "#F9F9FA",
  muted: "#6D7178",
  dark: "#333538",
  bg: "#0A0A0B",
};

const TRANSITION = 15;

// ─── Scene 1: Credibility Filter ───────────────────────────────────────────

const CREDIBILITY_ITEMS = [
  {
    icon: "🔄",
    label: "Username Changes",
    sub: "Multiple renames = recycled identity",
    risk: "HIGH",
    riskColor: "#EF4444",
  },
  {
    icon: "📅",
    label: "Account Age vs Following",
    sub: "New account + large audience = red flag",
    risk: "HIGH",
    riskColor: "#EF4444",
  },
  {
    icon: "📍",
    label: "Location Mismatch",
    sub: "Claimed city vs declared country",
    risk: "REVIEW",
    riskColor: "#F5BC38",
  },
];

const CredibilityCard: React.FC<{
  item: (typeof CREDIBILITY_ITEMS)[number];
  delay: number;
}> = ({ item, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const translateY = interpolate(progress, [0, 1], [50, 0]);

  return (
    <div
      style={{
        opacity: progress,
        transform: `translateY(${translateY}px)`,
        backgroundColor: "rgba(255,255,255,0.03)",
        border: "1.5px solid rgba(255,255,255,0.07)",
        borderLeft: `4px solid ${item.riskColor}`,
        borderRadius: 20,
        padding: "36px 44px",
        display: "flex",
        alignItems: "center",
        gap: 40,
        width: 920,
      }}
    >
      <div style={{ fontSize: 52 }}>{item.icon}</div>
      <div style={{ flex: 1 }}>
        <div
          style={{
            fontSize: 36,
            fontWeight: 700,
            color: COLORS.light,
            marginBottom: 10,
          }}
        >
          {item.label}
        </div>
        <div
          style={{
            fontSize: 26,
            fontWeight: 600,
            color: COLORS.muted,
          }}
        >
          {item.sub}
        </div>
      </div>
      <div
        style={{
          backgroundColor: `${item.riskColor}18`,
          border: `1.5px solid ${item.riskColor}55`,
          borderRadius: 10,
          padding: "10px 24px",
          fontSize: 24,
          fontWeight: 700,
          color: item.riskColor,
          letterSpacing: "0.15em",
        }}
      >
        {item.risk}
      </div>
    </div>
  );
};

const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const titleProgress = spring({
    frame,
    fps: f,
    delay: 5,
    config: { damping: 200 },
  });
  const titleY = interpolate(titleProgress, [0, 1], [-40, 0]);

  const badgeProgress = spring({
    frame,
    fps: f,
    delay: 120,
    config: { damping: 200 },
  });
  const badgeScale = interpolate(badgeProgress, [0, 1], [0.85, 1]);

  return (
    <AbsoluteFill
      style={{
        fontFamily: "sans-serif",
        background: `radial-gradient(ellipse at 25% 30%, rgba(158,162,168,0.07) 0%, ${COLORS.bg} 65%)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        paddingBottom: 120,
      }}
    >
      {/* Title */}
      <div
        style={{
          opacity: titleProgress,
          transform: `translateY(${titleY}px)`,
          fontSize: 64,
          fontWeight: 700,
          color: COLORS.accent,
          letterSpacing: "0.2em",
          textTransform: "uppercase",
          marginBottom: 80,
          textAlign: "center",
        }}
      >
        Credibility Filter
      </div>

      {/* Cards */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 28,
          alignItems: "center",
        }}
      >
        {CREDIBILITY_ITEMS.map((item, i) => (
          <CredibilityCard key={i} item={item} delay={30 + i * 18} />
        ))}
      </div>

      {/* Badge */}
      <div
        style={{
          opacity: badgeProgress,
          transform: `scale(${badgeScale})`,
          marginTop: 72,
          backgroundColor: "rgba(158,162,168,0.06)",
          border: "1.5px solid rgba(158,162,168,0.25)",
          borderRadius: 20,
          padding: "28px 72px",
          fontSize: 32,
          fontWeight: 700,
          color: COLORS.accent,
          letterSpacing: "0.15em",
          textTransform: "uppercase",
        }}
      >
        Sort & filter in a spreadsheet in minutes
      </div>
    </AbsoluteFill>
  );
};

// ─── Scene 2: Pipeline Steps ─────────────────────────────────────────────────

const PIPELINE_STEPS = [
  { icon: "🕷️", label: "Scrape Profiles", sub: "Apify Actor" },
  { icon: "📊", label: "Google Sheets", sub: "Auto-populate" },
  { icon: "⚙️", label: "n8n / Zapier", sub: "Trigger logic" },
];

const PipelineNode: React.FC<{
  step: (typeof PIPELINE_STEPS)[number];
  delay: number;
  showArrow: boolean;
}> = ({ step, delay, showArrow }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const translateY = interpolate(progress, [0, 1], [50, 0]);

  const arrowProgress = spring({
    frame,
    fps: f,
    delay: delay + 12,
    config: { damping: 200 },
  });

  return (
    <div style={{ display: "flex", alignItems: "center", gap: 32 }}>
      <div
        style={{
          opacity: progress,
          transform: `translateY(${translateY}px)`,
          backgroundColor: "rgba(255,255,255,0.04)",
          border: "1.5px solid rgba(255,255,255,0.08)",
          borderRadius: 24,
          padding: "48px 52px",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 18,
          width: 300,
        }}
      >
        <div style={{ fontSize: 60 }}>{step.icon}</div>
        <div
          style={{
            fontSize: 34,
            fontWeight: 700,
            color: COLORS.light,
            textAlign: "center",
          }}
        >
          {step.label}
        </div>
        <div
          style={{
            fontSize: 24,
            fontWeight: 600,
            color: COLORS.muted,
            textAlign: "center",
          }}
        >
          {step.sub}
        </div>
      </div>

      {showArrow && (
        <svg
          width="80"
          height="32"
          viewBox="0 0 80 32"
          style={{ opacity: arrowProgress, flexShrink: 0 }}
        >
          <line
            x1="4"
            y1="16"
            x2={4 + 58 * arrowProgress}
            y2="16"
            stroke={COLORS.accent}
            strokeWidth="2"
            strokeLinecap="round"
            opacity={0.5}
          />
          <path
            d={`M62 8l12 8-12 8`}
            stroke={COLORS.accent}
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            fill="none"
            opacity={arrowProgress * 0.6}
          />
        </svg>
      )}
    </div>
  );
};

const SceneTwo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const titleProgress = spring({
    frame,
    fps: f,
    delay: 5,
    config: { damping: 200 },
  });
  const titleY = interpolate(titleProgress, [0, 1], [-40, 0]);

  const badgeProgress = spring({
    frame,
    fps: f,
    delay: 120,
    config: { damping: 200 },
  });
  const badgeScale = interpolate(badgeProgress, [0, 1], [0.85, 1]);

  return (
    <AbsoluteFill
      style={{
        fontFamily: "sans-serif",
        background: `radial-gradient(ellipse at 70% 25%, rgba(158,162,168,0.07) 0%, ${COLORS.bg} 65%)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        paddingBottom: 120,
      }}
    >
      {/* Title */}
      <div
        style={{
          opacity: titleProgress,
          transform: `translateY(${titleY}px)`,
          fontSize: 64,
          fontWeight: 700,
          color: COLORS.accent,
          letterSpacing: "0.2em",
          textTransform: "uppercase",
          marginBottom: 80,
          textAlign: "center",
        }}
      >
        Automated Pipeline
      </div>

      {/* Pipeline row */}
      <div style={{ display: "flex", alignItems: "center", gap: 0 }}>
        {PIPELINE_STEPS.map((step, i) => (
          <PipelineNode
            key={i}
            step={step}
            delay={30 + i * 20}
            showArrow={i < PIPELINE_STEPS.length - 1}
          />
        ))}
      </div>

      {/* Badge */}
      <div
        style={{
          opacity: badgeProgress,
          transform: `scale(${badgeScale})`,
          marginTop: 80,
          backgroundColor: "rgba(158,162,168,0.06)",
          border: "1.5px solid rgba(158,162,168,0.25)",
          borderRadius: 20,
          padding: "28px 72px",
          fontSize: 32,
          fontWeight: 700,
          color: COLORS.accent,
          letterSpacing: "0.15em",
          textTransform: "uppercase",
        }}
      >
        Runs automatically on every new scrape
      </div>
    </AbsoluteFill>
  );
};

// ─── Scene 3: Threshold Routing ──────────────────────────────────────────────

const THRESHOLD_FACTORS = [
  { label: "Account Age", icon: "📅" },
  { label: "Verified Status", icon: "✅" },
  { label: "Username Stability", icon: "🔒" },
  { label: "Location Match", icon: "📍" },
];

const FactorChip: React.FC<{
  factor: (typeof THRESHOLD_FACTORS)[number];
  delay: number;
}> = ({ factor, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const translateY = interpolate(progress, [0, 1], [30, 0]);

  return (
    <div
      style={{
        opacity: progress,
        transform: `translateY(${translateY}px)`,
        backgroundColor: "rgba(255,255,255,0.04)",
        border: "1.5px solid rgba(255,255,255,0.08)",
        borderRadius: 40,
        padding: "18px 40px",
        display: "flex",
        alignItems: "center",
        gap: 16,
        fontSize: 28,
        fontWeight: 600,
        color: COLORS.light,
      }}
    >
      <span style={{ fontSize: 32 }}>{factor.icon}</span>
      {factor.label}
    </div>
  );
};

const RouteCard: React.FC<{
  icon: string;
  label: string;
  sub: string;
  color: string;
  delay: number;
  slideFrom: number;
}> = ({ icon, label, sub, color, delay, slideFrom }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const translateX = interpolate(progress, [0, 1], [slideFrom, 0]);

  return (
    <div
      style={{
        opacity: progress,
        transform: `translateX(${translateX}px)`,
        backgroundColor: "rgba(255,255,255,0.04)",
        border: `1.5px solid ${color}44`,
        borderTop: `4px solid ${color}`,
        borderRadius: 24,
        padding: "44px 56px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 20,
        width: 420,
        textAlign: "center",
      }}
    >
      <div style={{ fontSize: 60 }}>{icon}</div>
      <div style={{ fontSize: 36, fontWeight: 700, color: COLORS.light }}>
        {label}
      </div>
      <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted }}>
        {sub}
      </div>
    </div>
  );
};

const SceneThree: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const titleProgress = spring({
    frame,
    fps: f,
    delay: 5,
    config: { damping: 200 },
  });
  const titleY = interpolate(titleProgress, [0, 1], [-40, 0]);

  const dividerProgress = spring({
    frame,
    fps: f,
    delay: 55,
    config: { damping: 200 },
  });

  const scoreProgress = spring({
    frame,
    fps: f,
    delay: 40,
    config: { damping: 200 },
  });
  const scoreY = interpolate(scoreProgress, [0, 1], [40, 0]);

  return (
    <AbsoluteFill
      style={{
        fontFamily: "sans-serif",
        background: `radial-gradient(ellipse at 50% 60%, rgba(158,162,168,0.06) 0%, ${COLORS.bg} 65%)`,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        paddingBottom: 100,
      }}
    >
      {/* Title */}
      <div
        style={{
          opacity: titleProgress,
          transform: `translateY(${titleY}px)`,
          fontSize: 64,
          fontWeight: 700,
          color: COLORS.accent,
          letterSpacing: "0.2em",
          textTransform: "uppercase",
          marginBottom: 60,
          textAlign: "center",
        }}
      >
        Score-Based Routing
      </div>

      {/* Factor chips */}
      <div
        style={{
          display: "flex",
          gap: 24,
          marginBottom: 60,
          flexWrap: "wrap",
          justifyContent: "center",
        }}
      >
        {THRESHOLD_FACTORS.map((factor, i) => (
          <FactorChip key={i} factor={factor} delay={20 + i * 12} />
        ))}
      </div>

      {/* Score badge */}
      <div
        style={{
          opacity: scoreProgress,
          transform: `translateY(${scoreY}px)`,
          backgroundColor: "rgba(255,255,255,0.04)",
          border: "1.5px solid rgba(255,255,255,0.12)",
          borderRadius: 16,
          padding: "20px 56px",
          fontSize: 30,
          fontWeight: 700,
          color: COLORS.muted,
          letterSpacing: "0.12em",
          marginBottom: 52,
        }}
      >
        CREDIBILITY THRESHOLD
      </div>

      {/* Routing split */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 56,
        }}
      >
        <RouteCard
          icon="✉️"
          label="Outreach CRM"
          sub="Score above threshold"
          color="#22C55E"
          delay={80}
          slideFrom={-80}
        />

        {/* Divider arrow */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 12,
            opacity: dividerProgress,
          }}
        >
          <svg width="48" height="48" viewBox="0 0 24 24">
            <path
              d="M7 16l-4-4 4-4"
              stroke={COLORS.muted}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
            />
            <path
              d="M17 8l4 4-4 4"
              stroke={COLORS.muted}
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
            />
            <path
              d="M3 12h18"
              stroke={COLORS.muted}
              strokeWidth="2"
              strokeLinecap="round"
              fill="none"
            />
          </svg>
          <div
            style={{
              fontSize: 22,
              fontWeight: 600,
              color: COLORS.muted,
              letterSpacing: "0.12em",
              textTransform: "uppercase",
            }}
          >
            AUTO
          </div>
        </div>

        <RouteCard
          icon="🚩"
          label="Manual Review"
          sub="Score below threshold"
          color="#EF4444"
          delay={80}
          slideFrom={80}
        />
      </div>
    </AbsoluteFill>
  );
};

// ─── Black Screen ─────────────────────────────────────────────────────────────

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── Root Composition ─────────────────────────────────────────────────────────

const MyVideo: React.FC = () => (
  <TransitionSeries>
    <TransitionSeries.Sequence durationInFrames={20}>
      <BlackScreen />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: 20 })}
    />

    <TransitionSeries.Sequence durationInFrames={230 + TRANSITION}>
      <SceneOne />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: TRANSITION })}
    />

    <TransitionSeries.Sequence durationInFrames={220 + TRANSITION}>
      <SceneTwo />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: TRANSITION })}
    />

    <TransitionSeries.Sequence durationInFrames={240 + TRANSITION}>
      <SceneThree />
    </TransitionSeries.Sequence>
    <TransitionSeries.Transition
      presentation={fade()}
      timing={linearTiming({ durationInFrames: 20 })}
    />

    <TransitionSeries.Sequence durationInFrames={25}>
      <BlackScreen />
    </TransitionSeries.Sequence>
  </TransitionSeries>
);

export default MyVideo;
